def get_reports(status=None, segmentation_type=None, country=None, external_report_id=None, sort=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0258000" if __import__("os").path.isdir("./environment_mix/0258000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-reports"

    def _now_utc():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _to_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _dt_iso(dt):
        if dt is None:
            return None
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _ensure_reqlog():
        # Observable dynamics: always persist a request row.
        # If a log collection exists, use it; otherwise create request_logs.json.
        fname = None
        for cand in ("request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        return fname, logs

    def _enforce_rate_and_log(pre_status):
        # Simple per-endpoint rate & daily quota using request_logs.json.
        fname, logs = _ensure_reqlog()
        now = _now_utc()
        window_start = now - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now.year, now.month, now.day)

        def _row_dt(r):
            if not isinstance(r, dict):
                return None
            if r.get("endpoint") != endpoint:
                return None
            return _to_dt(r.get("timestamp"))

        per_min = 240
        per_day = 20000
        cnt_min = 0
        cnt_day = 0
        for r in logs:
            dt = _row_dt(r)
            if dt is None:
                continue
            if dt >= window_start:
                cnt_min += 1
            if dt >= day_start:
                cnt_day += 1
        if cnt_min >= per_min:
            # log rejection
            rid = "audreq_" + hashlib.sha1((endpoint + "|" + _dt_iso(now) + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:20]
            logs.append({"id": rid, "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": 0, "timestamp": _dt_iso(now)})
            _save(fname, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if cnt_day >= per_day:
            rid = "audreq_" + hashlib.sha1((endpoint + "|" + _dt_iso(now) + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:20]
            logs.append({"id": rid, "endpoint": endpoint, "status": "QUOTA_EXCEEDED", "latency_ms": 0, "timestamp": _dt_iso(now)})
            _save(fname, logs)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return fname, logs

    # Validate
    allowed_status = {"created", "syncing", "ready", "failed", "archived"}
    allowed_seg = {"none", "auto", "demographics", "interests", "affinity", "behavioral", "geography", "custom"}
    allowed_sort = {"created_at", "-created_at", "updated_at", "-updated_at", "last_synced_at", "-last_synced_at", "audience_size", "-audience_size", "name", "-name"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        pre = _enforce_rate_and_log("VALIDATION_ERROR")
        if isinstance(pre, dict) and pre.get("error"):  # already error
            return pre
        fname, logs = pre
        logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalid|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                     "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000),
                     "timestamp": _dt_iso(_now_utc())})
        _save(fname, logs)
        return _err("VALIDATION_ERROR", "Invalid status value", field="status", allowed=sorted(list(allowed_status)))
    if segmentation_type is not None and (not isinstance(segmentation_type, str) or segmentation_type not in allowed_seg):
        pre = _enforce_rate_and_log("VALIDATION_ERROR")
        if isinstance(pre, dict) and pre.get("error"):
            return pre
        fname, logs = pre
        logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalid|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                     "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000),
                     "timestamp": _dt_iso(_now_utc())})
        _save(fname, logs)
        return _err("VALIDATION_ERROR", "Invalid segmentation_type value", field="segmentation_type", allowed=sorted(list(allowed_seg)))
    if country is not None and not isinstance(country, str):
        pre = _enforce_rate_and_log("VALIDATION_ERROR")
        if isinstance(pre, dict) and pre.get("error"):
            return pre
        fname, logs = pre
        logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalid|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                     "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000),
                     "timestamp": _dt_iso(_now_utc())})
        _save(fname, logs)
        return _err("VALIDATION_ERROR", "country must be a string", field="country")
    if external_report_id is not None and not isinstance(external_report_id, str):
        pre = _enforce_rate_and_log("VALIDATION_ERROR")
        if isinstance(pre, dict) and pre.get("error"):
            return pre
        fname, logs = pre
        logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalid|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                     "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000),
                     "timestamp": _dt_iso(_now_utc())})
        _save(fname, logs)
        return _err("VALIDATION_ERROR", "external_report_id must be a string", field="external_report_id")
    if sort is None:
        sort = "-updated_at"
    if not isinstance(sort, str) or sort not in allowed_sort:
        pre = _enforce_rate_and_log("VALIDATION_ERROR")
        if isinstance(pre, dict) and pre.get("error"):
            return pre
        fname, logs = pre
        logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalid|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                     "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000),
                     "timestamp": _dt_iso(_now_utc())})
        _save(fname, logs)
        return _err("VALIDATION_ERROR", "Invalid sort value", field="sort", allowed=sorted(list(allowed_sort)))
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        pre = _enforce_rate_and_log("VALIDATION_ERROR")
        if isinstance(pre, dict) and pre.get("error"):
            return pre
        fname, logs = pre
        logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalid|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                     "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000),
                     "timestamp": _dt_iso(_now_utc())})
        _save(fname, logs)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit", minimum=1, maximum=200)
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            pre = _enforce_rate_and_log("VALIDATION_ERROR")
            if isinstance(pre, dict) and pre.get("error"):
                return pre
            fname, logs = pre
            logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalid|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                         "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000),
                         "timestamp": _dt_iso(_now_utc())})
            _save(fname, logs)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or payload.get("endpoint") != endpoint:
                raise ValueError("bad cursor")
            offset = int(payload.get("offset", 0))
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            pre = _enforce_rate_and_log("VALIDATION_ERROR")
            if isinstance(pre, dict) and pre.get("error"):
                return pre
            fname, logs = pre
            logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalidcursor|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                         "endpoint": endpoint, "status": "VALIDATION_ERROR", "latency_ms": int((time.time()-t0)*1000),
                         "timestamp": _dt_iso(_now_utc())})
            _save(fname, logs)
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    # Rate/quota check (and obtain log buffer)
    pre = _enforce_rate_and_log("OK")
    if isinstance(pre, dict) and pre.get("error"):
        return pre
    log_fname, logs = pre

    # Load and filter
    rows = _load("intelligence_reports.json")
    if not isinstance(rows, list):
        rows = []
    filtered = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        # Default exclude archived unless explicitly filtered to archived
        if status is None and r.get("status") == "archived":
            continue
        if status is not None and r.get("status") != status:
            continue
        if segmentation_type is not None and r.get("segmentation_type") != segmentation_type:
            continue
        if country is not None and r.get("country") != country:
            continue
        if external_report_id is not None and r.get("external_report_id") != external_report_id:
            continue
        filtered.append(r)

    # Sort
    desc = sort.startswith("-")
    key = sort[1:] if desc else sort

    def _sort_key(r):
        v = r.get(key)
        if key in ("created_at", "updated_at", "last_synced_at"):
            dt = _to_dt(v)
            # Put None last always
            return (1, datetime.datetime.min) if dt is None else (0, dt)
        if key in ("audience_size",):
            if v is None:
                return (1, 0)
            if isinstance(v, int):
                return (0, v)
            return (0, 0)
        if key in ("name",):
            if v is None:
                return (1, "")
            return (0, str(v).lower())
        return (0, v)

    filtered.sort(key=_sort_key, reverse=desc)

    total = len(filtered)
    page = filtered[offset:offset + limit]
    next_cursor = None
    has_more = offset + limit < total
    if has_more:
        payload = {"v": 1, "endpoint": endpoint, "offset": offset + limit}
        enc = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    # Log success
    logs.append({
        "id": "audreq_" + hashlib.sha1((endpoint + "|" + _dt_iso(_now_utc()) + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
        "endpoint": endpoint,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "timestamp": _dt_iso(_now_utc()),
        "result_count": len(page)
    })
    _save(log_fname, logs)

    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}
    }

def get_report_info(report_id, include_segments=None, **_extra):
    import json, os, datetime, time, base64, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0258000" if __import__("os").path.isdir("./environment_mix/0258000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.utcnow()

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            return dt.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status_code, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ended = time.time()
        row = {
            "id": f"audlog_{base64.b32encode(os.urandom(10)).decode('utf-8').rstrip('=').upper()}",
            "endpoint": "get-report-info",
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int(round((ended - started) * 1000)),
            "created_at": _iso(now),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(report_id, str) or not re.match(r"^audrpt_[0-9A-HJKMNP-TV-Z]{17,}$", report_id):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid report_id format.", field="report_id")

    if include_segments is None:
        include_segments = False
    if not isinstance(include_segments, bool):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid include_segments value.", field="include_segments")

    reports = _load("intelligence_reports.json")
    if not isinstance(reports, list):
        reports = []

    report = None
    for r in reports:
        if isinstance(r, dict) and r.get("id") == report_id:
            report = r
            break

    # Not accessible if archived (no internal flag exposed)
    if not report or report.get("status") == "archived":
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Report not found.", report_id=report_id)

    resp = {"report": report}

    if include_segments:
        segs = _load("report_segments.json")
        if not isinstance(segs, list):
            segs = []
        report_segs = [s for s in segs if isinstance(s, dict) and s.get("report_id") == report_id]

        # Order by rank asc, nulls last
        def _rank_key(s):
            rk = s.get("rank")
            if rk is None:
                return (1, 0)
            if isinstance(rk, int):
                return (0, rk)
            return (0, 0)

        report_segs.sort(key=_rank_key)
        resp["segments"] = report_segs

        # Business rule: ready report must have >=1 segment ready/syncing unless segmentation_type='none'
        if report.get("status") == "ready" and report.get("segmentation_type") != "none":
            ok = any(s.get("status") in ("ready", "syncing") for s in report_segs)
            if not ok:
                # Surface as conflict/invalid state; keep consistent with transition/state correctness
                _log(409, error_code="CONFLICT")
                return _err("CONFLICT", "Report is marked ready but has no ready/syncing segments.", report_id=report_id)

    # Business rule: must include access_links when report ready
    if report.get("status") == "ready":
        if report.get("access_links") is None:
            # not an error, but ensure field present for caller
            resp["report"] = dict(report)
            resp["report"]["access_links"] = None

    _log(200)
    return {"data": resp}

def get_audience_insights(audience_id, baseline_id=None, categories=None, time_range=None, refresh=None, **_extra):
    import json, os, datetime, time, base64, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0258000" if __import__("os").path.isdir("./environment_mix/0258000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.utcnow()

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            return dt.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status_code, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ended = time.time()
        row = {
            "id": f"audlog_{base64.b32encode(os.urandom(10)).decode('utf-8').rstrip('=').upper()}",
            "endpoint": "get-audience-insights",
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int(round((ended - started) * 1000)),
            "created_at": _iso(now),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(audience_id, str) or not re.match(r"^audaud_[0-9A-HJKMNP-TV-Z]{17,}$", audience_id):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid audience_id format.", field="audience_id")

    if baseline_id is not None:
        if not isinstance(baseline_id, str) or not re.match(r"^audref_[0-9A-HJKMNP-TV-Z]{17,}$", baseline_id):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid baseline_id format.", field="baseline_id")

    if categories is not None:
        if not isinstance(categories, list) or any(not isinstance(x, str) for x in categories):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid categories; must be an array of strings.", field="categories")

    if time_range is not None:
        if not isinstance(time_range, dict):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid time_range; must be an object.", field="time_range")
        if any(k not in ("from", "to") for k in time_range.keys()):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid time_range fields.", field="time_range")
        frm = _parse_dt(time_range.get("from")) if time_range.get("from") is not None else None
        to = _parse_dt(time_range.get("to")) if time_range.get("to") is not None else None
        if time_range.get("from") is not None and frm is None:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid time_range.from datetime.", field="time_range.from")
        if time_range.get("to") is not None and to is None:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid time_range.to datetime.", field="time_range.to")
        if frm and to and frm > to:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "time_range.from must be <= time_range.to.", field="time_range")

    if refresh is None:
        refresh = False
    if not isinstance(refresh, bool):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid refresh value.", field="refresh")

    audiences = _load("audiences.json")
    if not isinstance(audiences, list):
        audiences = []
    aud = None
    for a in audiences:
        if isinstance(a, dict) and a.get("id") == audience_id:
            aud = a
            break
    if not aud or aud.get("status") == "deleted":
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Audience not found.", audience_id=audience_id)

    # Validate baseline exists and is usable if provided
    if baseline_id is not None:
        refs = _load("reference_data.json")
        if not isinstance(refs, list):
            refs = []
        base = None
        for r in refs:
            if isinstance(r, dict) and r.get("id") == baseline_id:
                base = r
                break
        if not base:
            _log(404, error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Baseline not found.", baseline_id=baseline_id)
        if base.get("ref_type") != "baseline":
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "baseline_id does not reference a baseline.", field="baseline_id")
        if base.get("status") not in ("active", "deprecated"):
            _log(409, error_code="CONFLICT")
            return _err("CONFLICT", "Baseline is not available for use.", baseline_id=baseline_id)

    def _fingerprint_categories(cats):
        if not cats:
            return ""
        norm = [c.strip() for c in cats if isinstance(c, str)]
        norm = [c for c in norm if c != ""]
        norm = sorted(set(norm))
        h = hashlib.sha256(("\n".join(norm)).encode("utf-8")).hexdigest()
        return "sha256:" + h

    def _fingerprint_time_range(tr):
        if not tr:
            return ""
        frm = tr.get("from")
        to = tr.get("to")
        s = json.dumps({"from": frm, "to": to}, separators=(",", ":"), sort_keys=True)
        return "sha256:" + hashlib.sha256(s.encode("utf-8")).hexdigest()

    cats_fp = _fingerprint_categories(categories)
    tr_fp = _fingerprint_time_range(time_range)

    artifacts = _load("audience_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    def _is_expired(row):
        exp = _parse_dt(row.get("expires_at"))
        if exp is None:
            return False
        return exp < now

    # Find newest ready artifact for this request shape
    candidates = []
    for ar in artifacts:
        if not isinstance(ar, dict):
            continue
        if ar.get("audience_id") != audience_id:
            continue
        if ar.get("artifact_type") != "insights":
            continue
        if ar.get("status") != "ready":
            continue
        if (ar.get("baseline_id") or None) != (baseline_id or None):
            continue
        # Stored categories/time_range are canonicalized by the caller; if missing treat as empty
        if (cats_fp or "") != (_fingerprint_categories(ar.get("categories")) or ""):
            continue
        if (tr_fp or "") != (_fingerprint_time_range(ar.get("time_range")) or ""):
            continue
        candidates.append(ar)

    def _computed_key(ar):
        dt = _parse_dt(ar.get("computed_at")) or _parse_dt(ar.get("updated_at")) or _parse_dt(ar.get("created_at")) or datetime.datetime.min
        return dt

    candidates.sort(key=_computed_key, reverse=True)
    latest_ready = candidates[0] if candidates else None

    if latest_ready and not _is_expired(latest_ready) and not refresh:
        _log(200)
        return {"data": {"artifact": latest_ready, "state": "ready", "cached": True}}

    if latest_ready and not _is_expired(latest_ready) and refresh:
        # Even if refresh requested, if it's not expired treat as cache hit (vendor behavior varies; this keeps effects reasonable)
        _log(200)
        return {"data": {"artifact": latest_ready, "state": "ready", "cached": True}}

    # If missing or expired -> enqueue recomputation by creating a queued artifact (idempotent if one already queued/computing)
    inflight = None
    for ar in artifacts:
        if not isinstance(ar, dict):
            continue
        if ar.get("audience_id") != audience_id or ar.get("artifact_type") != "insights":
            continue
        if (ar.get("baseline_id") or None) != (baseline_id or None):
            continue
        if (cats_fp or "") != (_fingerprint_categories(ar.get("categories")) or ""):
            continue
        if (tr_fp or "") != (_fingerprint_time_range(ar.get("time_range")) or ""):
            continue
        if ar.get("status") in ("queued", "computing"):
            inflight = ar
            break

    if inflight is None:
        new_id = f"audart_{base64.b32encode(os.urandom(10)).decode('utf-8').rstrip('=').upper()}"
        row = {
            "id": new_id,
            "audience_id": audience_id,
            "artifact_type": "insights",
            "categories": categories if categories is not None else None,
            "baseline_id": baseline_id,
            "time_range": time_range if time_range is not None else None,
            "payload": {"state": "queued"},
            "payload_schema_version": 1,
            "computed_at": None,
            "expires_at": None,
            "status": "queued",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        artifacts.append(row)
        _save("audience_artifacts.json", artifacts)
        inflight = row

    # Bounded blocking simulation: if a queued/computing artifact has been updated very recently and is ready, return it.
    # Offline backend cannot compute; return retriable state.
    _log(202)
    return {"data": {"artifact": inflight, "state": inflight.get("status"), "cached": False, "retriable": True}}

def get_baselines(country=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0258000" if __import__("os").path.isdir("./environment_mix/0258000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.utcnow()

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            return dt.replace(tzinfo=datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return dt

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _log(status_code, credential_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ended = time.time()
        row = {
            "id": f"audlog_{base64.b32encode(os.urandom(10)).decode('utf-8').rstrip('=').upper()}",
            "endpoint": "get-baselines",
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int(round((ended - started) * 1000)),
            "created_at": _iso(now),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        cfgs = _load("service_quotas.json")
        if not isinstance(cfgs, list):
            cfgs = []
        cfg = None
        for c in cfgs:
            if isinstance(c, dict) and c.get("service") == "audiense_insights":
                cfg = c
                break
        if not cfg:
            return None
        rpm = cfg.get("requests_per_minute")
        if not isinstance(rpm, int) or rpm <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        window_start = now - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "get-baselines":
                continue
            t = _parse_dt(r.get("created_at"))
            if t and t >= window_start:
                cnt += 1
        if cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _enforce_rate_limit()
    if rl:
        _log(429, error_code="RATE_LIMIT")
        return rl

    if country is not None and not isinstance(country, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid country value.", field="country")

    valid_status = {"active", "deprecated", "disabled"}
    if status is not None and (not isinstance(status, str) or status not in valid_status):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status value.", field="status")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.", field="limit")

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) > 2048:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "o" not in obj or not isinstance(obj["o"], int) or obj["o"] < 0:
                raise ValueError("bad cursor")
            offset = obj["o"]
        except Exception:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    refs = _load("reference_data.json")
    if not isinstance(refs, list):
        refs = []

    out = []
    for r in refs:
        if not isinstance(r, dict):
            continue
        if r.get("ref_type") != "baseline":
            continue
        # Business rule: by default only active/deprecated
        if status is None:
            if r.get("status") not in ("active", "deprecated"):
                continue
        else:
            if r.get("status") != status:
                continue
        # Country behavior: include matching + global (null) when filter applied
        if country is not None:
            rc = r.get("country")
            if rc is not None and rc != country:
                continue
            # keep rc==country or rc==None
        out.append(r)

    # Stable ordering: name asc then key asc
    def _nm(r):
        return ((r.get("name") or "").lower(), (r.get("key") or "").lower(), r.get("id") or "")
    out.sort(key=_nm)

    total = len(out)
    page = out[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = None
    if has_more:
        obj = {"o": offset + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log(200)
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more
        }
    }

def get_categories(status=None, country=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0258000" if __import__("os").path.isdir("./environment_mix/0258000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-categories"

    def _now_utc():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _to_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _dt_iso(dt):
        if dt is None:
            return None
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _ensure_reqlog():
        fname = None
        for cand in ("request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        return fname, logs

    def _enforce_rate_and_log_stub():
        fname, logs = _ensure_reqlog()
        now = _now_utc()
        window_start = now - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now.year, now.month, now.day)

        per_min = 240
        per_day = 20000

        cnt_min = 0
        cnt_day = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != endpoint:
                continue
            dt = _to_dt(r.get("timestamp"))
            if dt is None:
                continue
            if dt >= window_start:
                cnt_min += 1
            if dt >= day_start:
                cnt_day += 1

        if cnt_min >= per_min:
            logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|ratelimit|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                         "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": 0, "timestamp": _dt_iso(now)})
            _save(fname, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if cnt_day >= per_day:
            logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|quota|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                         "endpoint": endpoint, "status": "QUOTA_EXCEEDED", "latency_ms": 0, "timestamp": _dt_iso(now)})
            _save(fname, logs)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return fname, logs

    # Validate
    allowed_status = {"active", "deprecated", "disabled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        pre = _enforce_rate_and_log_stub()
        if isinstance(pre, dict) and pre.get("error"):
            return pre
        fname, logs = pre
        logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalid|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                     "endpoint": endpoint, "status": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "timestamp": _dt_iso(_now_utc())})
        _save(fname, logs)
        return _err("VALIDATION_ERROR", "Invalid status value", field="status", allowed=sorted(list(allowed_status)))
    if country is not None and not isinstance(country, str):
        pre = _enforce_rate_and_log_stub()
        if isinstance(pre, dict) and pre.get("error"):
            return pre
        fname, logs = pre
        logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalid|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                     "endpoint": endpoint, "status": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "timestamp": _dt_iso(_now_utc())})
        _save(fname, logs)
        return _err("VALIDATION_ERROR", "country must be a string", field="country")
    if limit is None:
        limit = 200
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        pre = _enforce_rate_and_log_stub()
        if isinstance(pre, dict) and pre.get("error"):
            return pre
        fname, logs = pre
        logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalidlimit|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                     "endpoint": endpoint, "status": "VALIDATION_ERROR",
                     "latency_ms": int((time.time()-t0)*1000), "timestamp": _dt_iso(_now_utc())})
        _save(fname, logs)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500", field="limit", minimum=1, maximum=500)

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            pre = _enforce_rate_and_log_stub()
            if isinstance(pre, dict) and pre.get("error"):
                return pre
            fname, logs = pre
            logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalidcursor|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                         "endpoint": endpoint, "status": "VALIDATION_ERROR",
                         "latency_ms": int((time.time()-t0)*1000), "timestamp": _dt_iso(_now_utc())})
            _save(fname, logs)
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if not isinstance(payload, dict) or payload.get("v") != 1 or payload.get("endpoint") != endpoint:
                raise ValueError("bad cursor")
            offset = int(payload.get("offset", 0))
            if offset < 0:
                raise ValueError("bad offset")
        except Exception:
            pre = _enforce_rate_and_log_stub()
            if isinstance(pre, dict) and pre.get("error"):
                return pre
            fname, logs = pre
            logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|invalidcursor2|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                         "endpoint": endpoint, "status": "VALIDATION_ERROR",
                         "latency_ms": int((time.time()-t0)*1000), "timestamp": _dt_iso(_now_utc())})
            _save(fname, logs)
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    pre = _enforce_rate_and_log_stub()
    if isinstance(pre, dict) and pre.get("error"):
        return pre
    log_fname, logs = pre

    ref = _load("reference_data.json")
    if not isinstance(ref, list):
        ref = []

    # Tool says optional status filter; business rule says active only by default for categories.
    eff_status = status if status is not None else "active"

    rows = []
    for r in ref:
        if not isinstance(r, dict):
            continue
        if r.get("ref_type") != "affinity_category":
            continue
        if eff_status is not None and r.get("status") != eff_status:
            continue
        if country is not None and r.get("country") not in (None, country):
            # reference_data constraint suggests country null for affinity_category, but keep safe
            continue
        rows.append(r)

    rows.sort(key=lambda x: ("" if x.get("name") is None else str(x.get("name")).lower()))

    total = len(rows)
    page = rows[offset:offset + limit]
    has_more = offset + limit < total
    next_cursor = None
    if has_more:
        payload = {"v": 1, "endpoint": endpoint, "offset": offset + limit}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    logs.append({
        "id": "audreq_" + hashlib.sha1((endpoint + "|" + _dt_iso(_now_utc()) + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
        "endpoint": endpoint,
        "status": "OK",
        "latency_ms": int((time.time() - t0) * 1000),
        "timestamp": _dt_iso(_now_utc()),
        "result_count": len(page)
    })
    _save(log_fname, logs)

    return {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}

def compare_audience_influencers(audience_id, categories, baseline_id=None, time_range=None, refresh=None, **_extra):
    import json, os, datetime, hashlib, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0258000" if __import__("os").path.isdir("./environment_mix/0258000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "compare-audience-influencers"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _dt_to_isoz(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(v):
        if v is None:
            return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0)

    def _ensure_reqlog():
        fname = None
        for cand in ("request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        return fname, logs

    def _new_id(prefix, rows):
        now = _utcnow()
        base = f"{prefix}|{_dt_to_isoz(now)}|{len(rows)}|{os.getpid()}"
        # keep vendor-ish prefix and base32-ish charset not guaranteed; datastore accepts strings
        return prefix + hashlib.sha1(base.encode("utf-8")).hexdigest()[:26]

    def _log(status_s, extra=None):
        fname, logs = _ensure_reqlog()
        now = _utcnow()
        row = {
            "id": _new_id("audreq_", logs),
            "endpoint": endpoint,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _dt_to_isoz(now),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    def _norm_categories(cat_keys):
        norm = []
        seen = set()
        for c in cat_keys:
            if not isinstance(c, str):
                return None
            k = c.strip()
            if not k:
                continue
            if k not in seen:
                seen.add(k)
                norm.append(k)
        norm.sort()
        return norm

    def _categories_fingerprint(norm_keys):
        raw = json.dumps(norm_keys, ensure_ascii=False, separators=(",", ":"))
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    def _time_range_fingerprint(fr_dt, to_dt):
        if fr_dt is None and to_dt is None:
            return ""
        raw = json.dumps(
            {"from": _dt_to_isoz(fr_dt), "to": _dt_to_isoz(to_dt)},
            ensure_ascii=False,
            separators=(",", ":"),
        )
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    try:
        # Validation
        if not isinstance(audience_id, str) or not re.match(r"^audaud_[0-9A-HJKMNP-TV-Z]{17,}$", audience_id):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid audience_id format", field="audience_id")

        if refresh is not None and not isinstance(refresh, bool):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "refresh must be boolean", field="refresh")

        if not isinstance(categories, list) or len(categories) == 0:
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "categories must be a non-empty array", field="categories")

        norm_keys = _norm_categories(categories)
        if norm_keys is None or len(norm_keys) == 0:
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "categories must be an array of non-empty strings", field="categories")

        if baseline_id is not None:
            if not isinstance(baseline_id, str) or not re.match(r"^audref_[0-9A-HJKMNP-TV-Z]{17,}$", baseline_id):
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid baseline_id format", field="baseline_id")

        fr_dt = None
        to_dt = None
        tr_obj = None
        if time_range is not None:
            if not isinstance(time_range, dict):
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "time_range must be an object", field="time_range")
            # additionalProperties=false enforced: only allow from/to keys
            for k in time_range.keys():
                if k not in ("from", "to"):
                    _log("error", {"error_code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", "time_range has unknown fields", field=f"time_range.{k}")
            if "from" in time_range:
                fr_dt = _parse_dt(time_range.get("from"))
                if fr_dt is None:
                    _log("error", {"error_code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", "Invalid time_range.from; must be RFC3339 date-time", field="time_range.from")
            if "to" in time_range:
                to_dt = _parse_dt(time_range.get("to"))
                if to_dt is None:
                    _log("error", {"error_code": "VALIDATION_ERROR"})
                    return _err("VALIDATION_ERROR", "Invalid time_range.to; must be RFC3339 date-time", field="time_range.to")
            if fr_dt is not None and to_dt is not None and fr_dt > to_dt:
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "time_range.from must be <= time_range.to", field="time_range")
            if fr_dt is not None or to_dt is not None:
                tr_obj = {}
                if fr_dt is not None:
                    tr_obj["from"] = _dt_to_isoz(fr_dt)
                if to_dt is not None:
                    tr_obj["to"] = _dt_to_isoz(to_dt)

        audiences = _load("audiences.json")
        if not isinstance(audiences, list):
            audiences = []
        aud_row = next((a for a in audiences if isinstance(a, dict) and a.get("id") == audience_id), None)
        if aud_row is None:
            _log("error", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Audience not found", audience_id=audience_id)

        # Validate category existence: reference_data ref_type=affinity_category AND status=active
        ref = _load("reference_data.json")
        if not isinstance(ref, list):
            ref = []
        active_cat_keys = set()
        for r in ref:
            if not isinstance(r, dict):
                continue
            if r.get("ref_type") == "affinity_category" and r.get("status") == "active":
                k = r.get("key")
                if isinstance(k, str):
                    active_cat_keys.add(k)
        missing = [k for k in norm_keys if k not in active_cat_keys]
        if missing:
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err(
                "VALIDATION_ERROR",
                "One or more categories are invalid or not active",
                field="categories",
                missing=missing,
                rule="categories must exist in reference_data where ref_type='affinity_category' and status='active'",
            )

        if baseline_id is not None:
            base = next((r for r in ref if isinstance(r, dict) and r.get("id") == baseline_id), None)
            if base is None:
                _log("error", {"error_code": "NOT_FOUND"})
                return _err("NOT_FOUND", "Baseline not found", baseline_id=baseline_id)
            if base.get("ref_type") != "baseline":
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "baseline_id must reference a baseline record", field="baseline_id")
            if base.get("status") not in ("active", "deprecated"):
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "baseline is not available for use", field="baseline_id", status=base.get("status"))

        artifacts = _load("audience_artifacts.json")
        if not isinstance(artifacts, list):
            artifacts = []

        cat_fp = _categories_fingerprint(norm_keys)
        tr_fp = _time_range_fingerprint(fr_dt, to_dt)

        def _parse_any_dt(v):
            dt = _parse_dt(v) if isinstance(v, str) else None
            return dt

        now = _utcnow()

        # Find latest ready artifact matching audience_id, artifact_type, baseline_id, categories fp, time_range fp
        matches = []
        for a in artifacts:
            if not isinstance(a, dict):
                continue
            if a.get("audience_id") != audience_id:
                continue
            if a.get("artifact_type") != "influencer_comparison":
                continue
            if (a.get("baseline_id") or None) != (baseline_id or None):
                continue
            payload = a.get("payload") if isinstance(a.get("payload"), dict) else {}
            if payload.get("categories_fingerprint") != cat_fp:
                continue
            if payload.get("time_range_fingerprint") != tr_fp:
                continue
            if a.get("status") == "ready":
                matches.append(a)

        def _sort_key(a):
            # newest by computed_at then updated_at then created_at
            for f in ("computed_at", "updated_at", "created_at"):
                dt = _parse_any_dt(a.get(f))
                if dt is not None:
                    return dt
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

        matches.sort(key=_sort_key, reverse=True)
        latest_ready = matches[0] if matches else None

        def _is_expired(row):
            exp = row.get("expires_at")
            if not exp:
                return False
            dt = _parse_any_dt(exp)
            if dt is None:
                return False
            return dt < now

        # Return cached if present and not expired and refresh is not true
        if latest_ready is not None and not _is_expired(latest_ready) and not (refresh is True):
            _log("ok", {"cache": "hit"})
            return {
                "audience_id": audience_id,
                "artifact": latest_ready,
                "cached": True,
                "status": latest_ready.get("status"),
            }

        # Enqueue recomputation (create new row) if no valid ready artifact
        new_row = {
            "id": _new_id("audart_", artifacts),
            "audience_id": audience_id,
            "artifact_type": "influencer_comparison",
            "categories": norm_keys,
            "baseline_id": baseline_id,
            "time_range": tr_obj,
            "payload": {
                "categories": norm_keys,
                "categories_fingerprint": cat_fp,
                "time_range": tr_obj,
                "time_range_fingerprint": tr_fp,
                "baseline_id": baseline_id,
                "state": "queued",
            },
            "payload_schema_version": 1,
            "computed_at": None,
            "expires_at": None,
            "status": "queued",
            "created_at": _dt_to_isoz(now),
            "updated_at": _dt_to_isoz(now),
        }
        artifacts.append(new_row)
        _save("audience_artifacts.json", artifacts)

        # Bounded "block until ready": only if there is already a computing/ready row to observe.
        # Offline store won't compute; so return retriable state consistent with vendor behavior.
        _log("ok", {"cache": "miss", "enqueued": True})
        return {
            "audience_id": audience_id,
            "artifact": new_row,
            "cached": False,
            "status": "queued",
            "retriable": True,
            "retry_after_seconds": 5,
        }
    except (TypeError, ValueError) as e:
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid input", detail=str(e))
    except OSError as e:
        _log("error", {"error_code": "CONFLICT"})
        return _err("CONFLICT", "Datastore I/O error", detail=str(e))

def get_audience_content(audience_id, baseline_id=None, time_range=None, refresh=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0258000" if __import__("os").path.isdir("./environment_mix/0258000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get-audience-content"

    def _now_utc():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _to_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _dt_iso(dt):
        if dt is None:
            return None
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _ensure_reqlog():
        fname = None
        for cand in ("request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        return fname, logs

    def _log(status, extra=None):
        fname, logs = _ensure_reqlog()
        now = _now_utc()
        row = {
            "id": "audreq_" + hashlib.sha1((endpoint + "|" + _dt_iso(now) + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _dt_iso(now),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    def _enforce_rate():
        fname, logs = _ensure_reqlog()
        now = _now_utc()
        window_start = now - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now.year, now.month, now.day)
        per_min = 180
        per_day = 15000
        cnt_min = 0
        cnt_day = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            dt = _to_dt(r.get("timestamp"))
            if dt is None:
                continue
            if dt >= window_start:
                cnt_min += 1
            if dt >= day_start:
                cnt_day += 1
        if cnt_min >= per_min:
            logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|ratelimit|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                         "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": 0, "timestamp": _dt_iso(now)})
            _save(fname, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if cnt_day >= per_day:
            logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|quota|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                         "endpoint": endpoint, "status": "QUOTA_EXCEEDED", "latency_ms": 0, "timestamp": _dt_iso(now)})
            _save(fname, logs)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    rl = _enforce_rate()
    if isinstance(rl, dict) and rl.get("error"):
        return rl

    # Validate
    if not isinstance(audience_id, str) or not re.match(r"^audaud_[0-9A-HJKMNP-TV-Z]{17,}$", audience_id):
        _log("VALIDATION_ERROR", {"audience_id": audience_id})
        return _err("VALIDATION_ERROR", "Invalid audience_id format", field="audience_id")
    if baseline_id is not None and (not isinstance(baseline_id, str) or not re.match(r"^audref_[0-9A-HJKMNP-TV-Z]{17,}$", baseline_id)):
        _log("VALIDATION_ERROR", {"audience_id": audience_id})
        return _err("VALIDATION_ERROR", "Invalid baseline_id format", field="baseline_id")
    if refresh is not None and not isinstance(refresh, bool):
        _log("VALIDATION_ERROR", {"audience_id": audience_id})
        return _err("VALIDATION_ERROR", "refresh must be a boolean", field="refresh")

    tr_from = tr_to = None
    if time_range is not None:
        if not isinstance(time_range, dict):
            _log("VALIDATION_ERROR", {"audience_id": audience_id})
            return _err("VALIDATION_ERROR", "time_range must be an object", field="time_range")
        if "from" in time_range:
            tr_from = _to_dt(time_range.get("from"))
            if tr_from is None:
                _log("VALIDATION_ERROR", {"audience_id": audience_id})
                return _err("VALIDATION_ERROR", "time_range.from must be RFC3339 date-time", field="time_range.from")
        if "to" in time_range:
            tr_to = _to_dt(time_range.get("to"))
            if tr_to is None:
                _log("VALIDATION_ERROR", {"audience_id": audience_id})
                return _err("VALIDATION_ERROR", "time_range.to must be RFC3339 date-time", field="time_range.to")
        if tr_from and tr_to and tr_from > tr_to:
            _log("VALIDATION_ERROR", {"audience_id": audience_id})
            return _err("VALIDATION_ERROR", "time_range.from must be <= time_range.to", field="time_range")

    audiences = _load("audiences.json")
    if not isinstance(audiences, list):
        audiences = []
    aud = next((a for a in audiences if isinstance(a, dict) and a.get("id") == audience_id), None)
    if aud is None:
        _log("NOT_FOUND", {"audience_id": audience_id})
        return _err("NOT_FOUND", "Audience not found", audience_id=audience_id)

    ref = _load("reference_data.json")
    if not isinstance(ref, list):
        ref = []
    if baseline_id is not None:
        base = next((r for r in ref if isinstance(r, dict) and r.get("id") == baseline_id and r.get("ref_type") == "baseline" and r.get("status") in ("active", "deprecated")), None)
        if base is None:
            _log("NOT_FOUND", {"audience_id": audience_id, "baseline_id": baseline_id})
            return _err("NOT_FOUND", "Baseline not found or not usable", baseline_id=baseline_id)

    def _tr_fp(tr):
        if tr is None:
            return ""
        raw = json.dumps(tr, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(raw.encode("utf-8")).hexdigest()

    tr_fp = _tr_fp(time_range)

    artifacts = _load("audience_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []
    now = _now_utc()

    def _is_expired(a):
        exp = _to_dt(a.get("expires_at"))
        return exp is not None and exp < now

    def _matches(a):
        if not isinstance(a, dict):
            return False
        if a.get("audience_id") != audience_id:
            return False
        if a.get("artifact_type") != "content_engagement":
            return False
        if (a.get("baseline_id") or None) != (baseline_id or None):
            return False
        if a.get("time_range_fingerprint") not in (None, tr_fp):
            return False
        return True

    ready = [a for a in artifacts if _matches(a) and a.get("status") == "ready" and not _is_expired(a)]
    ready.sort(key=lambda x: (_to_dt(x.get("computed_at")) or datetime.datetime.min, _to_dt(x.get("updated_at")) or datetime.datetime.min), reverse=True)
    if ready and not refresh:
        _log("OK", {"audience_id": audience_id, "artifact_id": ready[0].get("id")})
        return {"data": ready[0], "meta": {"cached": True}}

    queued = [a for a in artifacts if _matches(a) and a.get("status") in ("queued", "computing") and not _is_expired(a)]
    queued.sort(key=lambda x: (_to_dt(x.get("updated_at")) or datetime.datetime.min), reverse=True)
    if queued:
        _log("OK", {"audience_id": audience_id, "artifact_id": queued[0].get("id"), "state": queued[0].get("status")})
        return {"data": queued[0], "meta": {"cached": False, "retriable": True}}

    def _gen_id(prefix):
        raw = hashlib.sha256((prefix + "|" + _dt_iso(now) + "|" + str(time.time_ns())).encode("utf-8")).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(raw, "big")
        out = []
        for _ in range(20):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return prefix + "_" + "".join(out)

    new_row = {
        "id": _gen_id("audart"),
        "audience_id": audience_id,
        "artifact_type": "content_engagement",
        "categories": None,
        "baseline_id": baseline_id,
        "time_range": time_range,
        "payload": {
            "status": "queued",
            "note": "Computation queued; retry this call to fetch when ready.",
            "inputs": {"audience_id": audience_id, "baseline_id": baseline_id, "time_range": time_range},
        },
        "payload_schema_version": 1,
        "computed_at": None,
        "expires_at": None,
        "status": "queued",
        "created_at": _dt_iso(now),
        "updated_at": _dt_iso(now),
        "time_range_fingerprint": tr_fp,
    }
    artifacts.append(new_row)
    _save("audience_artifacts.json", artifacts)
    _log("OK", {"audience_id": audience_id, "artifact_id": new_row["id"], "state": "queued"})
    return {"data": new_row, "meta": {"cached": False, "retriable": True}}

def report_summary(report_id, summary_format, prompt_profile=None, refresh=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0258000" if __import__("os").path.isdir("./environment_mix/0258000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "report-summary"

    def _now_utc():
        return datetime.datetime.utcnow().replace(microsecond=0)

    def _to_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _dt_iso(dt):
        if dt is None:
            return None
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _ensure_reqlog():
        fname = None
        for cand in ("request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        return fname, logs

    def _log(status, extra=None):
        fname, logs = _ensure_reqlog()
        now = _now_utc()
        row = {
            "id": "audreq_" + hashlib.sha1((endpoint + "|" + _dt_iso(now) + "|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _dt_iso(now),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    def _enforce_rate():
        fname, logs = _ensure_reqlog()
        now = _now_utc()
        window_start = now - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now.year, now.month, now.day)
        per_min = 60
        per_day = 5000
        cnt_min = 0
        cnt_day = 0
        for r in logs:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            dt = _to_dt(r.get("timestamp"))
            if dt is None:
                continue
            if dt >= window_start:
                cnt_min += 1
            if dt >= day_start:
                cnt_day += 1
        if cnt_min >= per_min:
            logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|ratelimit|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                         "endpoint": endpoint, "status": "RATE_LIMIT", "latency_ms": 0, "timestamp": _dt_iso(now)})
            _save(fname, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if cnt_day >= per_day:
            logs.append({"id": "audreq_" + hashlib.sha1((endpoint + "|quota|" + str(len(logs))).encode("utf-8")).hexdigest()[:20],
                         "endpoint": endpoint, "status": "QUOTA_EXCEEDED", "latency_ms": 0, "timestamp": _dt_iso(now)})
            _save(fname, logs)
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    rl = _enforce_rate()
    if isinstance(rl, dict) and rl.get("error"):
        return rl

    # Validate
    if not isinstance(report_id, str) or not re.match(r"^audrpt_[0-9A-HJKMNP-TV-Z]{17,}$", report_id):
        _log("VALIDATION_ERROR", {"report_id": report_id})
        return _err("VALIDATION_ERROR", "Invalid report_id format", field="report_id")
    if not isinstance(summary_format, str) or summary_format not in ("markdown", "html", "json"):
        _log("VALIDATION_ERROR", {"report_id": report_id})
        return _err("VALIDATION_ERROR", "Invalid summary_format", field="summary_format", allowed=["markdown", "html", "json"])
    if prompt_profile is not None and not isinstance(prompt_profile, str):
        _log("VALIDATION_ERROR", {"report_id": report_id})
        return _err("VALIDATION_ERROR", "prompt_profile must be a string", field="prompt_profile")
    if refresh is not None and not isinstance(refresh, bool):
        _log("VALIDATION_ERROR", {"report_id": report_id})
        return _err("VALIDATION_ERROR", "refresh must be a boolean", field="refresh")

    reports = _load("intelligence_reports.json")
    if not isinstance(reports, list):
        reports = []
    report = next((r for r in reports if isinstance(r, dict) and r.get("id") == report_id), None)
    if report is None:
        _log("NOT_FOUND", {"report_id": report_id})
        return _err("NOT_FOUND", "Report not found", report_id=report_id)

    # Business rule: only generate/return ready summary if report status is ready
    if report.get("status") != "ready":
        _log("INVALID_TRANSITION", {"report_id": report_id, "report_status": report.get("status")})
        return _err("INVALID_TRANSITION", "Report is not ready for summarization", report_id=report_id, report_status=report.get("status"))

    summaries = _load("report_summaries.json")
    if not isinstance(summaries, list):
        summaries = []
    segments = _load("report_segments.json")
    if not isinstance(segments, list):
        segments = []
    artifacts = _load("audience_artifacts.json")
    if not isinstance(artifacts, list):
        artifacts = []

    # Compute staleness watermark: latest updated_at among segments for report and underlying ready artifacts for their audiences
    segs = [s for s in segments if isinstance(s, dict) and s.get("report_id") == report_id and s.get("status") != "archived"]
    latest_input_dt = _to_dt(report.get("updated_at")) or datetime.datetime.min
    for s in segs:
        latest_input_dt = max(latest_input_dt, _to_dt(s.get("updated_at")) or datetime.datetime.min)
        aid = s.get("audience_id")
        if aid:
            # newest ready insights/content/influencer artifacts affect summary freshness
            for a in artifacts:
                if not isinstance(a, dict):
                    continue
                if a.get("audience_id") != aid:
                    continue
                if a.get("status") != "ready":
                    continue
                latest_input_dt = max(latest_input_dt, _to_dt(a.get("updated_at")) or datetime.datetime.min)

    # Find existing summary row for (report_id, summary_format, prompt_profile)
    def _pp(v):
        return v if v is not None else ""

    existing_idx = None
    for i, s in enumerate(summaries):
        if not isinstance(s, dict):
            continue
        if s.get("report_id") == report_id and s.get("summary_format") == summary_format and _pp(s.get("prompt_profile")) == _pp(prompt_profile):
            existing_idx = i
            break

    now = _now_utc()

    def _gen_id(prefix):
        raw = hashlib.sha256((prefix + "|" + _dt_iso(now) + "|" + str(time.time_ns())).encode("utf-8")).digest()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        n = int.from_bytes(raw, "big")
        out = []
        for _ in range(20):
            n, r = divmod(n, 32)
            out.append(alphabet[r])
        return prefix + "_" + "".join(out)

    # If we have an existing ready summary and not refresh, return it; but mark stale if inputs newer
    if existing_idx is not None and not refresh:
        existing = summaries[existing_idx]
        gen_dt = _to_dt(existing.get("generated_at")) or datetime.datetime.min
        if existing.get("status") == "ready" and latest_input_dt > gen_dt:
            existing["status"] = "stale"
            existing["updated_at"] = _dt_iso(now)
            summaries[existing_idx] = existing
            _save("report_summaries.json", summaries)
        _log("OK", {"report_id": report_id, "summary_id": existing.get("id"), "summary_status": existing.get("status")})
        return {"data": existing, "meta": {"cached": True}}

    # If existing is queued/generating, return retriable state (no success without effect; read returns row)
    if existing_idx is not None and summaries[existing_idx].get("status") in ("queued", "generating"):
        existing = summaries[existing_idx]
        _log("OK", {"report_id": report_id, "summary_id": existing.get("id"), "summary_status": existing.get("status")})
        return {"data": existing, "meta": {"cached": False, "retriable": True}}

    # Enqueue generation by creating/updating summary row -> queued
    payload = {
        "format": summary_format,
        "prompt_profile": prompt_profile,
        "report": {"id": report.get("id"), "name": report.get("name"), "external_report_id": report.get("external_report_id")},
        "note": "Summary generation queued; retry to fetch when ready.",
    }

    if existing_idx is None:
        row = {
            "id": _gen_id("audsum"),
            "report_id": report_id,
            "summary_format": summary_format,
            "prompt_profile": prompt_profile,
            "payload": payload,
            "generated_at": None,
            "status": "queued",
            "created_at": _dt_iso(now),
            "updated_at": _dt_iso(now),
        }
        summaries.append(row)
        _save("report_summaries.json", summaries)
