def create_report(external_report_id, name=None, segmentation_type=None, country=None, audience_size=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0258000" if __import__("os").path.isdir("./environment_mix/0258000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create-report"

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _dt_to_isoz(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _ensure_reqlog():
        fname = None
        for cand in ("request_logs.json", "requests.json", "audit_log.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                fname = cand
                break
        if fname is None:
            fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        return fname, logs

    def _new_id(prefix, rows):
        now = _utcnow()
        base = f"{prefix}|{_dt_to_isoz(now)}|{len(rows)}|{os.getpid()}"
        return prefix + hashlib.sha1(base.encode("utf-8")).hexdigest()[:26]

    def _log(status, extra=None):
        fname, logs = _ensure_reqlog()
        now = _utcnow()
        row = {
            "id": _new_id("audreq_", logs),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _dt_to_isoz(now),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    try:
        if not isinstance(external_report_id, str) or not external_report_id.strip():
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "external_report_id must be a non-empty string", field="external_report_id")

        if name is not None:
            if not isinstance(name, str):
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "name must be a string", field="name")
            if not (1 <= len(name) <= 200):
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "name length must be between 1 and 200", field="name")

        allowed_seg = ["none", "auto", "demographics", "interests", "affinity", "behavioral", "geography", "custom"]
        if segmentation_type is not None:
            if not isinstance(segmentation_type, str) or segmentation_type not in allowed_seg:
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "Invalid segmentation_type", field="segmentation_type", allowed=allowed_seg)

        if country is not None:
            if not isinstance(country, str):
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "country must be a string", field="country")
            # Enforce datastore constraint: null OR length==2
            if len(country) != 2:
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "country must be a 2-letter ISO-3166-1 alpha-2 code", field="country")

        if audience_size is not None:
            if not isinstance(audience_size, int):
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "audience_size must be an integer", field="audience_size")
            if audience_size < 0:
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "audience_size must be >= 0", field="audience_size")

        reports = _load("intelligence_reports.json")
        if not isinstance(reports, list):
            reports = []

        # Unique(external_report_id)
        for r in reports:
            if isinstance(r, dict) and r.get("external_report_id") == external_report_id:
                # Idempotency: if the same payload was previously created, return the existing row.
                same = True
                if name is not None and r.get("name") != name:
                    same = False
                if segmentation_type is not None and r.get("segmentation_type") != segmentation_type:
                    same = False
                if country is not None and r.get("country") != country:
                    same = False
                if audience_size is not None and r.get("audience_size") != audience_size:
                    same = False
                if same:
                    _log("ok", {"idempotent": True, "report_id": r.get("id")})
                    return {"report": r}
                _log("error", {"error_code": "CONFLICT"})
                return _err("CONFLICT", "external_report_id already exists", field="external_report_id", external_report_id=external_report_id)

        now = _utcnow()
        report_id = _new_id("audrpt_", reports)
        row = {
            "id": report_id,
            "external_report_id": external_report_id,
            "name": name if name is not None else external_report_id,
            "segmentation_type": segmentation_type if segmentation_type is not None else "auto",
            "audience_size": audience_size,
            "country": country,
            "status": "created",
            "access_links": None,
            "last_synced_at": None,
            "created_at": _dt_to_isoz(now),
            "updated_at": _dt_to_isoz(now),
        }
        reports.append(row)
        _save("intelligence_reports.json", reports)

        _log("ok", {"report_id": report_id})
        return {"report": row}
    except Exception as e:
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

def update_report(report_id, name=None, country=None, status=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0258000" if __import__("os").path.isdir("./environment_mix/0258000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # Validate report_id format
    if not isinstance(report_id, str) or not re.match(r"^audrpt_[0-9A-HJKMNP-TV-Z]{17,}$", report_id):
        return _err("VALIDATION_ERROR", "Invalid report_id format", field="report_id")

    if name is not None:
        if not isinstance(name, str):
            return _err("VALIDATION_ERROR", "name must be a string", field="name")
        if not (1 <= len(name) <= 200):
            return _err("VALIDATION_ERROR", "name length must be between 1 and 200", field="name")
    if country is not None:
        if not isinstance(country, str):
            return _err("VALIDATION_ERROR", "country must be a string", field="country")
        if len(country) != 2:
            return _err("VALIDATION_ERROR", "country must be a 2-letter code", field="country")

    allowed_status = ["created", "syncing", "ready", "failed", "archived"]
    transitions = {
        "created": ["syncing", "archived"],
        "syncing": ["ready", "failed", "archived"],
        "ready": ["syncing", "archived"],
        "failed": ["syncing", "archived"],
        "archived": [],
    }
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=allowed_status)

    reports = _load("intelligence_reports.json")
    segments = _load("report_segments.json")
    summaries = _load("report_summaries.json")

    idx = None
    for i, r in enumerate(reports):
        if isinstance(r, dict) and r.get("id") == report_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Report not found", report_id=report_id)

    r = reports[idx]
    prev_updated_at = r.get("updated_at")

    # Apply field updates
    changed = False
    if name is not None and name != r.get("name"):
        r["name"] = name
        changed = True
    if country is not None and country != r.get("country"):
        r["country"] = country
        changed = True

    # Status transition
    if status is not None and status != r.get("status"):
        cur = r.get("status")
        if cur not in transitions:
            return _err("INVALID_TRANSITION", "Current report status is invalid", current=cur)
        if status not in transitions[cur]:
            return _err("INVALID_TRANSITION", "Illegal status transition", from_status=cur, to_status=status)
        # If transitioning to ready, enforce: at least 1 segment ready/syncing unless segmentation_type == 'none'
        if status == "ready" and r.get("segmentation_type") != "none":
            ok = False
            for s in segments:
                if isinstance(s, dict) and s.get("report_id") == report_id and s.get("status") in ("ready", "syncing"):
                    ok = True
                    break
            if not ok:
                return _err("INVALID_TRANSITION", "Report cannot be set to ready without at least one active segment", rule="ready_requires_segment")
        # Set status and timestamps
        r["status"] = status
        if status == "syncing":
            r["last_synced_at"] = None
        changed = True

    if not changed:
        return _err("VALIDATION_ERROR", "No changes requested")

    # Update updated_at
    r["updated_at"] = now
    reports[idx] = r

    # If any underlying artifacts/segments update after a ready summary, summary becomes stale.
    # Here, changes to report metadata/status count as underlying updates; mark ready summaries stale.
    for sm in summaries:
        if isinstance(sm, dict) and sm.get("report_id") == report_id and sm.get("status") == "ready":
            sm["status"] = "stale"
            sm["updated_at"] = now

    _save("intelligence_reports.json", reports)
    _save("report_summaries.json", summaries)

    return {"data": r}

def create_report_segment(report_id, audience_id, name, external_segment_id=None, description=None, rank=None, **_extra):
    import json, os, datetime, time, re, hashlib

