    def _new_id(prefix, rows):
        now = _utcnow()
        base = f"{prefix}|{_isoz(now)}|{len(rows)}|{os.getpid()}"
        h = hashlib.sha1(base.encode("utf-8")).hexdigest().upper()
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        out = []
        for ch in h:
            out.append(alphabet[int(ch, 16) % len(alphabet)])
            if len(out) >= 26:
                break
        return prefix + "".join(out)

    def _log(status, extra=None):
        fname, logs = _ensure_reqlog()
        now = _utcnow()
        row = {
            "id": _new_id("audreq_", logs),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _isoz(now),
        }
        if isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save(fname, logs)

    try:
        # validate ids
        if not isinstance(report_id, str) or not re.match(r"^audrpt_[0-9A-HJKMNP-TV-Z]{17,}$", report_id):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid report_id format", field="report_id")

        # IMPORTANT: accept any string matching the declared pattern (previous code rejected valid ids)
        if not isinstance(audience_id, str) or not re.match(r"^audaud_[0-9A-HJKMNP-TV-Z]{17,}$", audience_id):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid audience_id format", field="audience_id")

        if not isinstance(name, str) or not (1 <= len(name) <= 200):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "name must be 1..200 characters", field="name")

        if external_segment_id is not None and not isinstance(external_segment_id, str):
            _log("error", {"error_code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "external_segment_id must be a string", field="external_segment_id")

        if description is not None:
            if not isinstance(description, str):
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "description must be a string", field="description")
            if len(description) > 2000:
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "description too long (max 2000)", field="description")

        if rank is not None:
            if not isinstance(rank, int) or rank < 0:
                _log("error", {"error_code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", "rank must be an integer >= 0", field="rank")

        reports = _load("intelligence_reports.json")
        if not isinstance(reports, list):
            reports = []
        report = next((r for r in reports if isinstance(r, dict) and r.get("id") == report_id), None)
        if report is None:
            _log("error", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Report not found", field="report_id")
        if report.get("status") == "archived":
            _log("error", {"error_code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Cannot create segment under an archived report", field="report_id")

        audiences = _load("audiences.json")
        if not isinstance(audiences, list):
            audiences = []
        aud = next((a for a in audiences if isinstance(a, dict) and a.get("id") == audience_id), None)
        if aud is None:
            _log("error", {"error_code": "NOT_FOUND"})
            return _err("NOT_FOUND", "Audience not found", field="audience_id")
        if aud.get("status") == "deleted":
            _log("error", {"error_code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Audience is deleted and cannot back a report segment", field="audience_id")

        segs = _load("report_segments.json")
        if not isinstance(segs, list):
            segs = []

        # unique(report_id, external_segment_id) when external_segment_id provided
        if external_segment_id is not None:
            for s in segs:
                if not isinstance(s, dict):
                    continue
                if s.get("report_id") == report_id and s.get("external_segment_id") == external_segment_id:
                    _log("error", {"error_code": "CONFLICT"})
                    return _err("CONFLICT", "A segment with this external_segment_id already exists for the report", field="external_segment_id")

        now = _utcnow()
        now_iso = _isoz(now)

        seg = {
            "id": _new_id("audseg_", segs),
            "report_id": report_id,
            "external_segment_id": external_segment_id or _new_id("seg_", segs),
            "audience_id": audience_id,
            "name": name,
            "description": description,
            "size": None,
            "rank": rank,
            "status": "created",
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        segs.append(seg)
        _save("report_segments.json", segs)

        # touch report.updated_at because children changed
        report["updated_at"] = now_iso
        _save("intelligence_reports.json", reports)

        # mark report summaries stale if any ready exist for this report
        sums = _load("report_summaries.json")
        if not isinstance(sums, list):
            sums = []
        changed = False
        for sm in sums:
            if isinstance(sm, dict) and sm.get("report_id") == report_id and sm.get("status") == "ready":
                sm["status"] = "stale"
                sm["updated_at"] = now_iso
                changed = True
        if changed:
            _save("report_summaries.json", sums)

        _log("ok", {"segment_id": seg["id"], "report_id": report_id})
        return seg

    except Exception as e:
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))

