        # if a ready summary exists for this report, mark it stale on segment update
        if report_id:
            sums = _load("report_summaries.json")
            if not isinstance(sums, list):
                sums = []
            sums_changed = False
            for sm in sums:
                if isinstance(sm, dict) and sm.get("report_id") == report_id and sm.get("status") == "ready":
                    sm["status"] = "stale"
                    sm["updated_at"] = now_iso
                    sums_changed = True
            if sums_changed:
                _save("report_summaries.json", sums)

        _log("ok", {"segment_id": seg.get("id")})
        return seg

    except Exception as e:
        _log("error", {"error_code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Unexpected error", detail=str(e))
